package com.aac.ieojwo.routine.domain;
import com.aac.ieojwo.common.domain.BaseTimeEntity;import com.aac.ieojwo.user.domain.AacUser;import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="routines")public class Routine extends BaseTimeEntity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="aac_user_id",nullable=false)private AacUser user;@Column(nullable=false,length=100)private String title;@Column(nullable=false,length=300)private String message;@Column(nullable=false)private LocalTime timeOfDay;@Column(nullable=false,length=40)private String daysOfWeek;@Column(nullable=false,length=50)private String timezone;@Column(nullable=false)private boolean enabled;private LocalDate lastTriggeredDate;protected Routine(){}public static Routine create(AacUser u,String title,String message,LocalTime time,String days,String zone){Routine r=new Routine();r.user=u;r.apply(title,message,time,days,zone,true);return r;}public void apply(String t,String m,LocalTime time,String days,String zone,boolean enabled){title=t.trim();message=m.trim();timeOfDay=time;daysOfWeek=days;timezone=zone;this.enabled=enabled;}public boolean due(ZonedDateTime now){return enabled&&daysOfWeek.contains(now.getDayOfWeek().name())&&!now.toLocalTime().isBefore(timeOfDay)&&now.toLocalTime().isBefore(timeOfDay.plusMinutes(1))&&!now.toLocalDate().equals(lastTriggeredDate);}public void triggered(LocalDate date){lastTriggeredDate=date;}public void disable(){enabled=false;}public Long getId(){return id;}public AacUser getUser(){return user;}public String getTitle(){return title;}public String getMessage(){return message;}public LocalTime getTimeOfDay(){return timeOfDay;}public String getDaysOfWeek(){return daysOfWeek;}public String getTimezone(){return timezone;}public boolean isEnabled(){return enabled;}public LocalDate getLastTriggeredDate(){return lastTriggeredDate;}}
